INSERT INTO `aplikasi_notes` VALUES (1,28,'uji_keamanan','Smoke test Epic F 2026-04-17 21:12:59',0,10,NULL,NULL,'2026-04-17 07:13:00','2026-04-17 07:13:00'),(2,28,'uji_keamanan','Smoke test Epic F 2026-04-17 21:14:24',0,10,NULL,NULL,'2026-04-17 07:14:25','2026-04-17 07:14:25'),(4,27,'uji_keamanan','Ditemukan potensi kerentanan pada proses unggah dokumen karena belum terdapat pembatasan tipe dan ukuran file. Perlu ditambahkan validasi ekstensi, validasi MIME type, serta pembatasan ukuran file.',0,1,NULL,NULL,'2026-05-24 20:38:19','2026-05-24 20:38:19'),(5,27,'perbaikan','Tim implementasi telah memperbaiki validasi form pengajuan aplikasi dan menambahkan pesan kesalahan agar pengguna lebih mudah memahami data yang harus dilengkapi.',0,1,NULL,NULL,'2026-05-24 20:38:39','2026-05-24 20:38:39'),(6,27,'uji_keamanan','Perlu dilakukan peningkatan minor pada validasi input di beberapa form agar sistem dapat menolak karakter khusus yang tidak diperlukan. Selain itu, pesan kesalahan perlu dibuat lebih informatif tanpa menampilkan detail teknis sistem. Pengelola juga disarankan melakukan retest setelah perbaikan minor',0,10,NULL,NULL,'2026-05-24 21:54:02','2026-05-24 21:54:02'),(7,27,'uji_keamanan','Perlu dilakukan peningkatan minor pada validasi input di beberapa form agar sistem dapat menolak karakter khusus yang tidak diperlukan. Selain itu, pesan kesalahan perlu dibuat lebih informatif tanpa menampilkan detail teknis sistem. Pengelola juga disarankan melakukan retest setelah perbaikan minor',0,10,NULL,NULL,'2026-05-24 21:55:24','2026-05-24 21:55:24'),(8,27,'uji_keamanan','Ringkasan Hasil Uji:\nPengujian keamanan telah dilakukan pada fitur utama aplikasi, meliputi proses autentikasi pengguna, pengelolaan data aplikasi, pengajuan aplikasi baru, unggah dokumen, verifikasi UAT, uji keamanan, serta proses deployment. Berdasarkan hasil pengujian, tidak ditemukan kerentanan kritis yang dapat mengganggu kerahasiaan, integritas, dan ketersediaan sistem. Validasi input, kontrol akses berbasis peran, serta pembatasan akses terhadap dokumen telah berjalan sesuai kebutuhan. Dengan demikian, aplika\n\nCatatan Perbaikan:\njhbvgcfgvhb',0,10,NULL,NULL,'2026-05-24 23:42:16','2026-05-24 23:42:16'),(12,33,'uji_keamanan','Ringkasan Hasil Uji:\nya\n\nCatatan Perbaikan:\nya',0,10,NULL,NULL,'2026-06-01 08:41:35','2026-06-01 08:44:30'),(13,35,'info','ya',0,1,NULL,NULL,'2026-06-04 20:59:08','2026-06-04 20:59:08'),(17,13,'perbaikan','ya',0,11,NULL,NULL,'2026-06-16 21:49:11','2026-06-16 21:49:11'),(18,13,'perbaikan','test',0,11,NULL,NULL,'2026-06-16 21:56:19','2026-06-16 21:56:19');
