--
-- Table structure for table `aplikasis`
--

DROP TABLE IF EXISTS `aplikasis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `aplikasis` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nama_layanan` varchar(255) NOT NULL,
  `nama_singkat` varchar(255) NOT NULL,
  `nama_aplikasi` varchar(255) NOT NULL,
  `jenis_layanan_aplikasi` enum('publik','internal') NOT NULL,
  `kode_unitOrganisasi` varchar(255) NOT NULL,
  `tipe_akuisisi` varchar(255) NOT NULL,
  `status` varchar(255) NOT NULL,
  `doc_pengajuan_path` varchar(255) DEFAULT NULL,
  `doc_permohonan_path` varchar(255) DEFAULT NULL,
  `doc_studi_kelayakan_path` varchar(255) DEFAULT NULL,
  `security_test_passed` tinyint(1) DEFAULT NULL,
  `security_tested_by` bigint(20) unsigned DEFAULT NULL,
  `security_tested_at` timestamp NULL DEFAULT NULL,
  `security_test_notes` text DEFAULT NULL,
  `deployed_staging_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deployed_staging_by` bigint(20) unsigned DEFAULT NULL,
  `deployed_production_at` timestamp NULL DEFAULT NULL,
  `deployed_production_by` bigint(20) unsigned DEFAULT NULL,
  `deployment_notes` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `aplikasis_nama_aplikasi_index` (`nama_aplikasi`),
  KEY `aplikasis_jenis_layanan_aplikasi_index` (`jenis_layanan_aplikasi`),
  KEY `aplikasis_status_index` (`status`),
  KEY `aplikasis_created_at_index` (`created_at`),
  KEY `aplikasis_updated_by_foreign` (`updated_by`),
  KEY `aplikasis_created_by_index` (`created_by`),
  KEY `aplikasis_security_tested_by_foreign` (`security_tested_by`),
  KEY `aplikasis_security_passed_status_idx` (`security_test_passed`,`status`),
  KEY `aplikasis_deployed_staging_by_foreign` (`deployed_staging_by`),
  KEY `aplikasis_deployed_production_by_foreign` (`deployed_production_by`),
  CONSTRAINT `aplikasis_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `aplikasis_deployed_production_by_foreign` FOREIGN KEY (`deployed_production_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `aplikasis_deployed_staging_by_foreign` FOREIGN KEY (`deployed_staging_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `aplikasis_security_tested_by_foreign` FOREIGN KEY (`security_tested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `aplikasis_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

